package dev.sablelife.testing;
import dev.sablelife.SableLife;import dev.sablelife.heart.*;import dev.sablelife.module.*;import dev.ryanhcode.sable.api.SubLevelAssemblyHelper;import dev.ryanhcode.sable.companion.math.BoundingBox3i;import net.minecraft.core.*;import net.minecraft.gametest.framework.*;import net.minecraft.world.item.*;import net.minecraft.world.inventory.*;import net.minecraft.core.component.DataComponents;import net.minecraft.network.chat.Component;import net.minecraft.world.level.GameType;import net.neoforged.neoforge.gametest.*;import java.util.*;
@GameTestHolder("sablelife_core_ui_tests") @PrefixGameTestTemplate(false)
public final class LootEditorGameTests {
 private static HeartBlockEntity core(GameTestHelper h){var l=h.getLevel();var p=h.absolutePos(new BlockPos(4,40,4));l.setBlockAndUpdate(p,SableLife.HEART.get().defaultBlockState());var b=SubLevelAssemblyHelper.assembleBlocks(l,p,List.of(p),new BoundingBox3i(p.getX(),p.getY(),p.getZ(),p.getX(),p.getY(),p.getZ()));return (HeartBlockEntity)l.getBlockEntity(b.getPlot().getCenterBlock());}
 @GameTest(template="combat",batch="loot_editor_core") public static void WholeBodyExplicitRulesCountBoundsAndCursorArePreserved(GameTestHelper h){var c=core(h);var p=TestActors.creative(h.getLevel());p.setPos(ModuleArena.corePosition(c));var menu=new HeartLootMenu(1,p.getInventory(),c);var cursor=new ItemStack(Items.DIAMOND,17);cursor.set(DataComponents.CUSTOM_NAME,Component.literal("Reward"));menu.setCarried(cursor);menu.clicked(0,0,ClickType.PICKUP,p);h.assertTrue(menu.action(p,c.modules().revision(),c.creatureId(),"quantity",9,"0")&&menu.action(p,c.modules().revision(),c.creatureId(),"rule",65,"0"),"Direct fields rejected");h.assertTrue(c.lootTemplates().getFirst().getCount()==9&&c.chance(0)==65&&menu.getCarried().getCount()==17&&c.lootTemplates().getFirst().getHoverName().getString().equals("Reward"),"Fields consumed cursor or lost components");menu.setCarried(ItemStack.EMPTY);menu.clicked(0,0,ClickType.PICKUP,p);h.assertTrue(c.lootTemplates().getFirst().getCount()==9,"Selection cleared sample");menu.clicked(0,1,ClickType.QUICK_MOVE,p);h.assertTrue(c.chance(0)==60,"Shift-right rule adjustment failed");h.assertTrue(!menu.action(p,c.modules().revision()-1,c.creatureId(),"rule",0,"0")&&!menu.action(p,c.modules().revision(),UUID.randomUUID(),"rule",0,"0")&&!menu.action(p,c.modules().revision(),c.creatureId(),"quantity",65,"0")&&!menu.action(p,c.modules().revision(),c.creatureId(),"rule",Double.NaN,"0"),"Unsafe edits accepted");var saved=c.saveWithoutMetadata(h.getLevel().registryAccess());var restored=new HeartBlockEntity(c.getBlockPos(),c.getBlockState());restored.loadWithComponents(saved,h.getLevel().registryAccess());h.assertTrue(restored.lootTemplates().getFirst().getCount()==9&&restored.chance(0)==60,"New editor did not persist");c.tryActivate(p);h.assertTrue(!menu.action(p,c.modules().revision(),c.creatureId(),"clear",0,"0"),"Alive loot editor changed samples");h.succeed();}
 @GameTest(template="combat",batch="loot_editor_module") public static void PartLootQuantityProbabilityAndWeightAreIndependent(GameTestHelper h){var c=core(h);var p=TestActors.creative(h.getLevel());p.setPos(ModuleArena.corePosition(c));var m=c.modules().add("loot");var menu=new VirtualLootMenu(1,p.getInventory(),c,m);var cursor=new ItemStack(Items.EMERALD,24);cursor.set(DataComponents.CUSTOM_NAME,Component.literal("Part trophy"));menu.setCarried(cursor);menu.clicked(0,0,ClickType.PICKUP,p);h.assertTrue(menu.action(p,c.modules().revision(),m.id(),"quantity",12,"0")&&menu.action(p,c.modules().revision(),m.id(),"rule",25,"0"),"Part fields rejected");h.assertTrue(menu.action(p,c.modules().revision(),m.id(),"weighted",1,"0")&&menu.action(p,c.modules().revision(),m.id(),"rule",400,"0")&&menu.action(p,c.modules().revision(),m.id(),"rolls",3,"0"),"Weighted authoring failed");h.assertTrue(menu.rule(0)==400&&menu.sample(0).getCount()==12&&menu.getCarried().getCount()==24,"Weight edited quantity or consumed items");menu.action(p,c.modules().revision(),m.id(),"weighted",0,"0");h.assertTrue(menu.rule(0)==25,"Switching mode lost chance");menu.setCarried(ItemStack.EMPTY);menu.clicked(0,0,ClickType.PICKUP,p);h.assertTrue(menu.sample(0).getCount()==12,"Empty-hand selection cleared module sample");h.assertTrue(!menu.action(p,c.modules().revision(),m.id(),"rule",101,"0")&&!menu.action(p,c.modules().revision(),m.id(),"rolls",28,"0")&&!menu.action(p,c.modules().revision(),m.id(),"quantity",1.5,"0"),"Bad field bounds accepted");var loaded=VirtualModule.load(m.save());h.assertTrue(loaded.lootSamples().getInt("Chance0")==25&&loaded.lootSamples().getInt("Weight0")==400,"Rules failed round trip");c.tryActivate(p);h.assertTrue(!menu.action(p,c.modules().revision(),m.id(),"quantity",1,"0"),"Active part loot edited");h.succeed();}
 @GameTest(template="combat",batch="loot_editor_inventory") public static void InventoryShiftCopiesWithoutMovingStacksAndGhostGesturesCannotExtract(GameTestHelper h){var c=core(h);var p=TestActors.creative(h.getLevel());p.setPos(ModuleArena.corePosition(c));var item=new ItemStack(Items.GOLD_INGOT,19);p.getInventory().setItem(9,item);var whole=new HeartLootMenu(1,p.getInventory(),c);h.assertTrue(whole.action(p,c.modules().revision(),c.creatureId(),"copy_inventory",0,"54"),"Whole explicit copy rejected");h.assertTrue(c.lootTemplates().getFirst().getCount()==19&&p.getInventory().getItem(9).getCount()==19,"Whole shift copy moved inventory");var m=c.modules().add("loot");var part=new VirtualLootMenu(2,p.getInventory(),c,m);h.assertTrue(part.action(p,c.modules().revision(),m.id(),"copy_inventory",0,"54"),"Part explicit copy rejected");h.assertTrue(part.sample(0).getCount()==19&&p.getInventory().getItem(9).getCount()==19,"Part shift copy moved inventory");part.clicked(0,1,ClickType.SWAP,p);part.clicked(0,1,ClickType.CLONE,p);part.clicked(0,1,ClickType.THROW,p);h.assertTrue(part.sample(0).getCount()==19&&part.getCarried().isEmpty()&&!part.canDragTo(part.getSlot(0))&&!part.canTakeItemForPickAll(item,part.getSlot(0)),"Ghost item extraction allowed");p.setGameMode(GameType.SURVIVAL);h.assertTrue(!whole.action(p,c.modules().revision(),c.creatureId(),"clear",0,"0")&&!part.action(p,c.modules().revision(),m.id(),"clear",0,"0"),"Survival edited loot");p.getInventory().setItem(9,ItemStack.EMPTY);h.succeed();}
 @GameTest(template="combat",batch="loot_editor_single_copy")
 public static void BulkQuickMoveCannotMultiplyGhostCopiesAndExplicitCopyIsOneSlot(GameTestHelper h){
  var c=core(h);var p=TestActors.creative(h.getLevel());p.setPos(ModuleArena.corePosition(c));
  p.getInventory().setItem(9,new ItemStack(Items.DIAMOND,23));
  var whole=new HeartLootMenu(1,p.getInventory(),c);
  for(int i=0;i<10;i++)whole.clicked(54,0,ClickType.QUICK_MOVE,p);
  h.assertTrue(c.lootTemplates().stream().allMatch(ItemStack::isEmpty),"Bulk transfer created whole-body ghost samples");
  int revision=c.modules().revision();
  h.assertTrue(whole.action(p,revision,c.creatureId(),"copy_inventory",0,"54"),"Explicit whole copy failed");
  h.assertTrue(!whole.action(p,revision,c.creatureId(),"copy_inventory",0,"54"),"Repeated stale request copied again");
  h.assertTrue(c.lootTemplates().stream().filter(v->!v.isEmpty()).count()==1&&c.lootTemplates().getFirst().getCount()==23,"One whole copy filled more than one slot or lost stack count");
  h.assertTrue(!whole.action(p,c.modules().revision(),c.creatureId(),"copy_inventory",0,"0"),"Template slot used as inventory source");
  var m=c.modules().add("loot");var part=new VirtualLootMenu(2,p.getInventory(),c,m);
  for(int i=0;i<10;i++)part.clicked(54,0,ClickType.QUICK_MOVE,p);
  h.assertTrue(part.sample(0).isEmpty(),"Bulk transfer created part ghost samples");
  revision=c.modules().revision();h.assertTrue(part.action(p,revision,m.id(),"copy_inventory",0,"54"),"Explicit part copy failed");
  h.assertTrue(!part.action(p,revision,m.id(),"copy_inventory",0,"54")&&!part.action(p,c.modules().revision(),m.id(),"copy_inventory",0,"90"),"Duplicate or invalid part copy accepted");
  h.assertTrue(part.sample(0).getCount()==23&&part.sample(1).isEmpty()&&p.getInventory().getItem(9).getCount()==23&&part.getCarried().isEmpty(),"One part copy duplicated samples or moved real items");
  p.getInventory().setItem(9,ItemStack.EMPTY);h.succeed();
 }

}
